import { describe, expect, it } from 'vitest'
import { validatePostExtraForm } from '../src/utils/postInspectionValidate'

describe('validatePostExtraForm bug7008', () => {
  it('空表单首错为整改措施', () => {
    expect(validatePostExtraForm({})).toBe('请输入整改措施')
  })
  it('缺期限', () => {
    expect(validatePostExtraForm({ rectifyMeasure: 'a' })).toBe('请选择整改期限')
  })
  it('缺现场照片', () => {
    expect(
      validatePostExtraForm({
        rectifyMeasure: 'm',
        rectifyDeadline: '2026-11-26',
        rectifyState: '待整改',
        rectifyUser: '张三',
      }),
    ).toBe('请上传现场照片')
  })
  it('全部有效', () => {
    expect(
      validatePostExtraForm({
        rectifyMeasure: 'm',
        rectifyDeadline: '2026-11-26',
        rectifyState: '待整改',
        rectifyUser: '张三',
        photos: [{ status: 'done', url: 'https://x/1.jpg' }],
      }),
    ).toBeNull()
  })
})

